VSAV.chap({
  id: 'mt-mesures', part: 'socle', seq: SOC2, title: 'Gestes techniques : mesures, examen et réchauffement', short: 'Mesures et réchauffement', motif: 'ecg', accent: '#0e7490',
  sources: ['FT - Mesure de la pression artérielle', 'FT - Mesure de la saturation pulsée en O₂', 'FT - Mesure de la température', 'FT - Mesure de la douleur', 'FT - Recherche de lésions', 'AC - Comment couvrir une victime', 'FT - Technique de réchauffement de victime'],
  summary: 'Pression artérielle (auscultation ou palpation), SpO₂ et ses pièges, température (thermomètre auriculaire et recommandations HAS), douleur (échelle numérique), recherche de lésions de la tête aux pieds, protection contre le froid et réchauffement.',
  why: '<b>Pourquoi mesurer ?</b> Les chiffres donnent au médecin régulateur une image objective de l’état de la victime et permettent d’en suivre l’évolution. Mais <b>aucune mesure ne doit retarder un geste d’urgence</b>, et chaque appareil a ses pièges : une SpO₂ « normale » chez un intoxiqué au CO est fausse.',
  sections: [
    { id: 'pa', t: 'La pression artérielle', ic: 'heart', src: 'FT - Mesure de la pression artérielle',
      html: '<p>Deux valeurs en mmHg : <b>systolique</b> (contraction du cœur) et <b>diastolique</b> (relâchement). Mesure au bilan secondaire et en surveillance, idéalement assis ou demi-assis, <b>brassard au niveau du cœur</b>, sur un bras non traumatisé, bord inférieur 2 cm au-dessus du pli du coude.</p>' +
        '<ul class="check"><li><b>Tensiomètre automatique</b> : repère sur l’artère (face interne du pli du coude), mesure automatique avec la fréquence cardiaque.</li><li><b>Manuel par auscultation</b> : gonfler jusqu’à disparition du bruit du pouls + 30 mmHg ; dégonfler : réapparition du bruit = systolique, disparition = diastolique.</li><li><b>Manuel par palpation</b> (bruit, traumatisme) : même principe au pouls radial ; ne donne que la systolique.</li><li>Prévenir la victime d’une possible douleur ; brassard laissé en place = dégonflé et peu serré. Un appareil peut ne rien afficher si la PA est très basse.</li></ul>' },
    { id: 'spo2', t: 'La saturation pulsée en oxygène (SpO₂)', ic: 'lungs', src: 'FT - Mesure de la saturation pulsée en O₂',
      html: '<p>Pourcentage d’oxygène transporté par le sang, normalement entre <b>94 et 100 %</b> ; guide l’administration d’oxygène. Capteur adapté à l’âge.</p>' +
        '<div class="callout bad"><b>Mesures non fiables</b>Victime agitée ou qui tremble, extrémités froides, détresse circulatoire, maladies vasculaires, <b>vernis à ongles</b>. <b>Intoxication aux fumées ou au CO : valeurs faussement rassurantes.</b></div>' },
    { id: 'temperature', t: 'La température', ic: 'sun', src: 'FT - Mesure de la température',
      html: '<p>Systématique en cas de suspicion d’hypothermie ou d’hyperthermie.</p><ul class="check"><li><b>Thermomètre auriculaire</b> : couvre-sonde neuf, tirer le pavillon de l’oreille <b>vers le haut et l’arrière</b>, sonde à l’entrée du conduit, mesurer ; couvre-sonde aux DASRI.</li><li>Pas chez le nourrisson de <b>moins de 3 mois</b> ni en cas de traumatisme des deux oreilles (explosion) ; chiffres erronés après un changement brusque de température ambiante.</li><li>Électronique : rectal, buccal ou axillaire (corriger de ½ à 1 °C selon le site).</li><li>Recommandations HAS : rectal de la naissance à 5 ans, buccal au-delà ; axillaire, tympanique ou frontal pour le dépistage.</li></ul>' },
    { id: 'douleur', t: 'La douleur', ic: 'alert', src: 'FT - Mesure de la douleur',
      html: '<p>Au SDIS 51 : <b>échelle numérique (EN)</b> de 0 à 10, à l’instant présent.</p><div class="tw"><table><thead><tr><th>Note</th><th>Douleur</th></tr></thead><tbody><tr><td>0</td><td>Absente</td></tr><tr><td>1 à 3</td><td>Faible</td></tr><tr><td>4 à 5</td><td>Modérée</td></tr><tr><td>6 à 7</td><td>Forte</td></tr><tr><td>8 à 10</td><td>Insupportable</td></tr></tbody></table></div><p>Mesurée pour toute victime douloureuse, <b>répétée</b> pendant la prise en charge et notée sur la fiche bilan ; attention aux incompréhensions (jeune âge, langue).</p>' },
    { id: 'lesions', t: 'La recherche de lésions', ic: 'eye', src: 'FT - Recherche de lésions',
      html: '<p>Orientée d’abord par les plaintes, complétée par un examen « <b>de la tête aux pieds</b> » si le traumatisme est violent ou la conscience altérée : regarder, palper doucement, comparer les deux côtés.</p><ul class="check"><li><b>Tête et cou</b> : plaies, hématomes, écoulement par le nez ou les oreilles, asymétrie du visage ou des pupilles — <b>tête maintenue</b> en cas de traumatisme.</li><li><b>Thorax</b> : plaie soufflante, soulèvement asymétrique, douleur.</li><li><b>Abdomen</b> : plaie, hématome, douleur localisée (repère horaire autour du nombril).</li><li><b>Dos</b> : mains glissées sans mobiliser, ou lors du relevage.</li><li><b>Bassin</b> : <b>observer seulement, ne pas palper</b> (déplacement de fracture, saignement interne).</li><li><b>Membres</b> : déformations, pouls, coloration, chaleur, motricité et sensibilité des doigts et orteils.</li></ul>' },
    { id: 'froid', t: 'Couvrir et réchauffer', ic: 'snow', src: 'AC - Comment couvrir une victime ; FT - Technique de réchauffement',
      html: '<p>L’hypothermie menace toute victime d’<b>hémorragie, de traumatisme ou de brûlure grave</b>, même sans grand froid ; enfants, personnes âgées, alcool, immobilité ou immersion la favorisent. Vêtements mouillés : <b>pertes de chaleur × 5</b>.</p><ul class="check"><li><b>Couvrir</b> (rayonnement) : drap + couverture, sans oublier mains, pieds et tête.</li><li><b>Isoler du sol</b> (conduction) : brancard, tapis, couverture dessous.</li><li><b>Protéger du vent et de l’humidité</b> : abri, retirer les vêtements mouillés, sécher, couverture isotherme.</li><li><b>Réchauffer</b> : endroit chaud, couverture chauffante (40-42 °C), bouillottes ou chaufferettes au cou, aux aisselles, aux plis de l’aine — <b>jamais directement sur la peau</b> (brûlure) ; mobilisation douce.</li></ul><p class="small muted">Voir aussi <a href="#/c/froid">Hypothermie et gelures</a>.</p>' }
  ],
  key: ['Aucune mesure ne retarde un geste d’urgence.', 'PA : brassard au niveau du cœur, 2 cm au-dessus du pli du coude.', 'SpO₂ normale 94-100 % ; fausse avec le CO, le vernis, le froid.', 'Thermomètre auriculaire : pas avant 3 mois.', 'Douleur : EN 0-10, répétée et notée.', 'Bassin : on regarde, on ne palpe pas.', 'Hypothermie : couvrir, isoler du sol, sécher, réchauffer sans brûler.'],
  memo: ['SpO₂ 94-100 % ; CO = faux normal', 'PA : +30 mmHg après disparition du pouls', 'Auriculaire : pavillon haut et arrière', 'EN : 0 / 1-3 / 4-5 / 6-7 / 8-10', 'Bassin : ne pas palper', 'Chaleur jamais au contact de la peau'],
  traps: ['Se rassurer d’une SpO₂ à 98 % chez un intoxiqué au CO.', 'Mesurer la SpO₂ sur un doigt verni ou glacé.', 'Palper le bassin.', 'Utiliser le thermomètre auriculaire chez un nourrisson de 2 mois.', 'Poser une bouillotte directement sur la peau.', 'Retarder une compression pour prendre la tension.'],
  quiz: [
    { q: 'Valeur normale de la SpO₂ :', c: ['94 à 100 %', '80 à 90 %', '50 à 70 %', '100 % uniquement'], e: 'FT Mesure de la SpO₂.', s: 'spo2' },
    { q: 'Chez un intoxiqué au monoxyde de carbone, la SpO₂ :', c: ['Donne des valeurs faussement rassurantes', 'Est toujours basse', 'Est parfaitement fiable', 'Ne s’affiche jamais'], e: 'FT Mesure de la SpO₂ : risques.', s: 'spo2' },
    { q: 'Mesure de la PA par palpation : quelle valeur obtient-on ?', c: ['La systolique seulement', 'La diastolique seulement', 'Les deux', 'La fréquence respiratoire'], e: 'FT Mesure de la pression artérielle.', s: 'pa' },
    { q: 'Thermomètre auriculaire : contre-indiqué chez :', c: ['Le nourrisson de moins de 3 mois', 'L’adulte', 'L’enfant de 6 ans', 'La personne âgée'], e: 'FT Mesure de la température.', s: 'temperature' },
    { q: 'Sur l’échelle numérique, une douleur à 6 ou 7 est :', c: ['Forte', 'Faible', 'Modérée', 'Absente'], e: 'FT Mesure de la douleur.', s: 'douleur' },
    { q: 'Lors de la recherche de lésions, le bassin :', c: ['S’observe sans être palpé', 'Se palpe fermement', 'Se comprime pour tester sa stabilité', 'N’est jamais examiné'], e: 'FT Recherche de lésions.', s: 'lesions' },
    { q: 'Où placer les bouillottes pour réchauffer une victime ?', c: ['Au cou, aux aisselles, aux plis de l’aine, avec une épaisseur de tissu', 'Directement sur la peau du ventre', 'Sous les pieds nus', 'Sur le visage'], e: 'FT Technique de réchauffement.', s: 'froid' },
    { q: 'Les vêtements mouillés multiplient les pertes de chaleur par :', c: ['5', '2', '10', '1 (aucun effet)'], e: 'FT Technique de réchauffement.', s: 'froid' }
  ]
});
